class Version(_BaseVersion):
    """Version class with major, minor, patch properties.

    This extends the base Version from conans.model.version to provide
    properties for accessing individual version components, matching the
    behavior expected in Conan 2.X.
    """

    @property
    def major(self):
        """Return the major component (first item) of the version."""
        self_list = self.as_list
        if not self_list or not isinstance(self_list[0], int):
            return self._base
        return str(self_list[0])

    @property
    def minor(self):
        """Return the minor component (second item) of the version."""
        self_list = self.as_list
        if not self_list or not isinstance(self_list[0], int):
            return self._base
        return str(self_list[1]) if len(self_list) > 1 else "0"

